pub(crate) fn find(key: &str) -> Option<&'static str> {
    if key >= "шевеливший" {
        return m23(key);
    }
    if key >= "хваставшийся" {
        return m22(key);
    }
    if key >= "усовершенствовавшийся" {
        return m21(key);
    }
    if key >= "укипавший" {
        return m20(key);
    }
    if key >= "трепыхавший" {
        return m19(key);
    }
    if key >= "сцепляющийся" {
        return m18(key);
    }
    if key >= "ссыпавший" {
        return m17(key);
    }
    if key >= "соразмерявший" {
        return m16(key);
    }
    if key >= "слипший" {
        return m15(key);
    }
    if key >= "серебрящий" {
        return m14(key);
    }
    if key >= "рубленный" {
        return m13(key);
    }
    if key >= "растрепывавший" {
        return m12(key);
    }
    if key >= "раскупавший" {
        return m11(key);
    }
    if key >= "размахивавший" {
        return m10(key);
    }
    if key >= "пхавший" {
        return m9(key);
    }
    if key >= "простегивающий" {
        return m8(key);
    }
    if key >= "пролеживающийся" {
        return m7(key);
    }
    if key >= "проворчавший" {
        return m6(key);
    }
    if key >= "пристроившийся" {
        return m5(key);
    }
    if key >= "приконченный" {
        return m4(key);
    }
    if key >= "предусматривающий" {
        return m3(key);
    }
    if key >= "потрушивавший" {
        return m2(key);
    }
    if key >= "попутешествовавший" {
        return m1(key);
    }
    m0(key)
}

